* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  background: var(--bg); color: var(--text);
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 14px; height: 100vh; overflow: hidden;
}
/* ===== 三栏布局：左栏(会话列表) 中栏(聊天) 右栏(监控) ===== */
.layout { display: grid; grid-template-columns: 200px 1fr 240px; height: 100vh; }

/* ---- 左栏：会话列表 ---- */
.sidebar {
  background: var(--panel); border-right: 1px solid var(--border);
  padding: 14px; display: flex; flex-direction: column; gap: 8px; overflow-y: auto;
}
.sidebar .logo { font-size: 17px; font-weight: 700; letter-spacing: .5px; margin-bottom: 12px; }
.sidebar .logo span { color: var(--accent); }
.sess {
  padding: 10px; border-radius: 8px; border: 1px solid transparent; cursor: pointer;
  font-size: 12.5px; line-height: 1.4;
}
.sess:hover { background: var(--panel-2); }
.sess.active { background: var(--panel-2); border-color: var(--accent); }
.sess .t { font-weight: 600; margin-bottom: 3px; }
.sess .m { color: var(--dim); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sess .badge { float: right; }

/* ---- 中栏：聊天主区 ---- */
.chat {
  display: flex; flex-direction: column; height: 100vh; min-width: 0;
}
.chat-head {
  padding: 12px 18px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; gap: 10px; background: var(--panel);
}
.chat-head .title { font-weight: 600; font-size: 15px; }
.chat-head .sub { color: var(--dim); font-size: 12px; }
.messages { flex: 1; overflow-y: auto; padding: 18px; display: flex; flex-direction: column; gap: 14px; }

/* 消息气泡 */
.msg { display: flex; gap: 10px; max-width: 92%; }
.msg.user { align-self: flex-end; flex-direction: row-reverse; }
.msg .avatar {
  width: 30px; height: 30px; border-radius: 8px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; font-size: 14px;
}
.msg.user .avatar { background: var(--accent); }
.msg.agent .avatar { background: var(--panel-2); border: 1px solid var(--border); }
.msg .body {
  padding: 10px 14px; border-radius: 12px; line-height: 1.65; white-space: pre-wrap;
  word-break: break-word;
}
.msg.user .body { background: var(--user-bubble); border-top-right-radius: 4px; }
.msg.agent .body { background: var(--agent-bubble); border: 1px solid var(--border); border-top-left-radius: 4px; }

/* 工具调用卡片 */
.tool-card {
  margin-top: 8px; border: 1px solid var(--border); border-radius: 8px;
  overflow: hidden; font-size: 12px; background: rgba(0,0,0,.2);
}
.tool-card .tool-head {
  padding: 6px 10px; display: flex; justify-content: space-between; align-items: center;
  cursor: pointer; background: rgba(255,255,255,.03);
}
.tool-card .tool-name { font-family: "JetBrains Mono", Consolas, monospace; font-weight: 600; }
.tool-card .tool-detail { padding: 8px 10px; border-top: 1px solid var(--border); font-family: monospace; white-space: pre-wrap; display: none; color: var(--dim); }
.tool-card.open .tool-detail { display: block; }
.tool-card.ok .tool-name { color: var(--green); }
.tool-card.err .tool-name { color: var(--red); }

/* 轮次分隔 */
.round-divider {
  display: flex; align-items: center; gap: 10px; margin: 6px 0; color: var(--dim); font-size: 11.5px;
}
.round-divider::before, .round-divider::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.round-divider .tag { padding: 2px 8px; border-radius: 10px; background: var(--panel-2); }

/* 整理横幅 */
