<title>Wovra · 任务控制台</title>
<style>
  :root {
    --bg: #0a0e14;
    --bg-soft: #0f1520;
    --panel: #131a26;
    --panel-2: #0d1320;
    --border: #1e2a3d;
    --text: #dbe4f0;
    --text-dim: #8ba0b8;
    --text-faint: #5a6f8a;
    --accent: #4f8cff;
    --accent-2: #22d3ee;
    --ok: #34d399;
    --warn: #fbbf24;
    --danger: #f87171;
    --purple: #a78bfa;
    --pink: #f472b6;
    --radius: 14px;
    --mono: "SF Mono", "JetBrains Mono", Consolas, "Courier New", monospace;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: -apple-system, "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif;
    min-height: 100vh;
    overflow-x: hidden;
  }
  /* ---- 背景光晕 ---- */
  .glow {
    position: fixed; inset: 0; pointer-events: none; z-index: 0;
    background:
      radial-gradient(600px 300px at 15% 0%, rgba(79,140,255,.10), transparent 60%),
      radial-gradient(500px 300px at 85% 10%, rgba(167,139,250,.08), transparent 60%),
      radial-gradient(700px 500px at 50% 110%, rgba(34,211,238,.05), transparent 60%);
  }
  .wrap { position: relative; z-index: 1; max-width: 1440px; margin: 0 auto; padding: 24px; }

  /* ---- 顶栏 ---- */
  header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 18px 24px; border: 1px solid var(--border); border-radius: var(--radius);
    background: linear-gradient(180deg, rgba(19,26,38,.9), rgba(13,19,32,.9));
    backdrop-filter: blur(8px); margin-bottom: 20px;
  }
  .logo { display: flex; align-items: center; gap: 14px; }
  .logo-mark {
    width: 40px; height: 40px; border-radius: 11px;
    background: linear-gradient(135deg, var(--accent), var(--purple));
    display: grid; place-items: center; font-weight: 800; font-size: 18px; color: #fff;
    box-shadow: 0 0 24px rgba(79,140,255,.35);
  }
  .logo h1 { font-size: 20px; letter-spacing: .5px; }
  .logo small { color: var(--text-dim); font-size: 12px; display: block; margin-top: 2px; }
  .status-pill {
    display: inline-flex; align-items: center; gap: 8px;
    padding: 7px 14px; border-radius: 999px; font-size: 13px;
    background: rgba(52,211,153,.08); border: 1px solid rgba(52,211,153,.25); color: var(--ok);
  }
  .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ok); animation: pulse 2s infinite; }
  @keyframes pulse { 0%,100% { opacity: 1 } 50% { opacity: .35 } }
  .header-right { display: flex; align-items: center; gap: 14px; }
  .task-id { font-family: var(--mono); font-size: 12px; color: var(--text-faint); }

  /* ---- 网格 ---- */
  .grid { display: grid; grid-template-columns: 320px 1fr 320px; gap: 20px; }
  @media (max-width: 1200px) { .grid { grid-template-columns: 1fr; } }

  /* ---- 面板 ---- */
  .panel {
    background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius);
    padding: 20px; margin-bottom: 20px;
  }
  .panel h2 {
    font-size: 13px; color: var(--text-dim); font-weight: 600; letter-spacing: 1.5px;
    text-transform: uppercase; margin-bottom: 16px; display: flex; align-items: center; gap: 8px;
  }
  .panel h2::before { content: ""; width: 4px; height: 14px; border-radius: 2px; background: var(--accent); }

  /* ---- 任务树 ---- */
  .tree-node { margin: 6px 0; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--border); background: var(--panel-2); font-size: 13px; }
  .tree-node .tag { display: inline-block; font-size: 10px; padding: 2px 7px; border-radius: 999px; margin-right: 8px; vertical-align: 1px; }
  .tag.goal { background: rgba(79,140,255,.15); color: var(--accent); }
  .tag.req { background: rgba(167,139,250,.15); color: var(--purple); }
  .tag.acc { background: rgba(52,211,153,.12); color: var(--ok); }
  .tag.state { background: rgba(251,191,36,.12); color: var(--warn); }
  .tree-node .title { font-weight: 600; }
  .tree-node .desc { color: var(--text-dim); margin-top: 4px; font-size: 12px; line-height: 1.6; }
  .tree-line { border-left: 2px dashed var(--border); margin-left: 18px; padding-left: 16px; }

  /* ---- 水位条 ---- */
  .watermark { margin: 12px 0 6px; }
  .wm-bar { position: relative; height: 18px; border-radius: 999px; background: var(--panel-2); border: 1px solid var(--border); overflow: hidden; }
  .wm-fill { height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); width: 0%; transition: width 1.2s cubic-bezier(.2,.8,.2,1); }
  .wm-fill.warn { background: linear-gradient(90deg, var(--warn), var(--danger)); }
  .wm-mark { position: absolute; top: 0; height: 100%; width: 2px; background: rgba(248,113,113,.7); }
  .wm-labels { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 11px; color: var(--text-dim); margin-top: 6px; }
  .wm-note { font-size: 11px; color: var(--text-faint); margin-top: 6px; line-height: 1.5; }

  /* ---- 上下文分层（缓存前缀） ---- */
  .ctx-block { margin: 4px 0; border-radius: 8px; padding: 8px 12px; font-size: 12px; display: flex; justify-content: space-between; align-items: center; }
  .ctx-block .name { font-weight: 600; }
  .ctx-block .meta { font-family: var(--mono); font-size: 11px; color: var(--text-dim); }
  .ctx-static { background: rgba(52,211,153,.10); border: 1px solid rgba(52,211,153,.22); }
  .ctx-dynamic { background: rgba(79,140,255,.08); border: 1px solid rgba(79,140,255,.18); }
  .ctx-current { background: rgba(167,139,250,.10); border: 1px solid rgba(167,139,250,.22); }
  .ctx-bracket { border-left: 2px solid var(--accent-2); padding-left: 14px; margin: 6px 0 6px 6px; }
  .ctx-label { font-size: 10px; color: var(--accent-2); letter-spacing: 1px; margin-bottom: 4px; }

  /* ---- 指标卡 ---- */
  .stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .stat { background: var(--panel-2); border: 1px solid var(--border); border-radius: 12px; padding: 14px; }
  .stat .label { font-size: 11px; color: var(--text-dim); }
  .stat .value { font-family: var(--mono); font-size: 22px; font-weight: 700; margin-top: 4px; }
  .stat .value small { font-size: 12px; color: var(--text-faint); font-weight: 400; }
  .stat .delta { font-size: 11px; margin-top: 3px; }
  .up { color: var(--ok); } .down { color: var(--danger); } .neutral { color: var(--text-dim); }

  /* ---- 时间线 ---- */
  .timeline { position: relative; padding-left: 26px; }
  .timeline::before { content: ""; position: absolute; left: 8px; top: 6px; bottom: 6px; width: 2px; background: var(--border); }
  .tl-item { position: relative; margin-bottom: 14px; }
  .tl-item::before {
    content: ""; position: absolute; left: -24px; top: 5px; width: 12px; height: 12px; border-radius: 50%;
    background: var(--panel); border: 2px solid var(--text-faint);
  }
  .tl-item.done::before { border-color: var(--ok); background: var(--ok); box-shadow: 0 0 10px rgba(52,211,153,.4); }
  .tl-item.org::before { border-color: var(--purple); background: var(--purple); box-shadow: 0 0 10px rgba(167,139,250,.4); }
  .tl-item .rid { font-family: var(--mono); font-size: 11px; color: var(--text-faint); }
  .tl-item .rgoal { font-size: 13px; margin-top: 2px; }
  .tl-item .rmeta { font-size: 11px; color: var(--text-dim); margin-top: 3px; font-family: var(--mono); }
  .tl-tag { font-size: 10px; padding: 1px 7px; border-radius: 999px; margin-left: 8px; }
  .tl-tag.org { background: rgba(167,139,250,.15); color: var(--purple); }

  /* ---- 组织/分裂图 ---- */
  .org-map { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  .org-node { padding: 12px 16px; border-radius: 12px; border: 1px solid var(--border); background: var(--panel-2); text-align: center; min-width: 110px; }
  .org-node.root { border-color: rgba(79,140,255,.4); background: rgba(79,140,255,.08); }
  .org-node .n-name { font-size: 13px; font-weight: 600; }
  .org-node .n-role { font-size: 10px; color: var(--text-dim); margin-top: 2px; font-family: var(--mono); }
  .org-arrow { color: var(--text-faint); font-size: 16px; }
  .org-split-note { font-size: 11px; color: var(--text-dim); margin-top: 12px; line-height: 1.7; }
  .org-split-note code { background: var(--panel-2); padding: 2px 6px; border-radius: 4px; font-family: var(--mono); color: var(--accent-2); font-size: 10px; }

  /* ---- 流式/日志 ---- */
  .log { font-family: var(--mono); font-size: 12px; background: #0a0f18; border: 1px solid var(--border); border-radius: 10px; padding: 12px; max-height: 180px; overflow-y: auto; }
  .log .l { color: var(--text-dim); padding: 2px 0; white-space: nowrap; }
  .log .l::before { content: "› "; color: var(--text-faint); }
  .log .l.hit { color: var(--ok); }
  .log .l.miss { color: var(--danger); }
  .log .l.org { color: var(--purple); }

  footer { text-align: center; color: var(--text-faint); font-size: 11px; padding: 30px 0 10px; font-family: var(--mono); }
</style>
</head>
