    --sans: -apple-system, "PingFang SC", "Segoe UI", "Microsoft YaHei", sans-serif;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background:
      radial-gradient(1200px 500px at 80% -10%, rgba(91,140,255,0.08), transparent 60%),
      radial-gradient(900px 400px at -10% 110%, rgba(139,91,255,0.07), transparent 60%),
