    color: var(--text);
    font-family: var(--sans);
    min-height: 100vh;
    font-size: 13px;
    line-height: 1.55;
  }
  ::-webkit-scrollbar { width: 8px; height: 8px; }
  ::-webkit-scrollbar-thumb { background: #2a3247; border-radius: 4px; }
  ::-webkit-scrollbar-track { background: transparent; }

  /* ---------- 顶栏 ---------- */
  .topbar {
    display: flex; align-items: center; gap: 20px;
    padding: 14px 28px;
    border-bottom: 1px solid var(--border);
    background: rgba(11,14,20,0.8);
    backdrop-filter: blur(8px);
    position: sticky; top: 0; z-index: 50;
  }
  .logo {
    font-family: var(--mono);
    font-weight: 700; font-size: 17px;
    letter-spacing: 0.5px;
    background: linear-gradient(90deg, var(--accent), var(--accent-2));
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent;
    display: flex; align-items: center; gap: 9px;
  }
  .logo .dot {
    width: 9px; height: 9px; border-radius: 50%;
    background: var(--green);
    box-shadow: 0 0 10px var(--green);
    -webkit-text-fill-color: initial;
  }
  .topbar .task-id {
    font-family: var(--mono); font-size: 12px; color: var(--text-faint);
    border: 1px solid var(--border); padding: 3px 10px; border-radius: 6px;
    background: var(--bg-2);
  }
  .topbar .spacer { flex: 1; }
  .badge {
    font-family: var(--mono); font-size: 11px;
    padding: 3px 10px; border-radius: 999px;
    border: 1px solid var(--border-2); color: var(--text-dim);
    background: var(--bg-2);
  }
  .badge.live { color: var(--green); border-color: rgba(52,211,153,0.35); }
  .badge.live::before {
    content: ""; display: inline-block; width: 6px; height: 6px;
    border-radius: 50%; background: var(--green); margin-right: 6px;
    animation: pulse 1.6s ease-in-out infinite;
  }
  @keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.35; } }

  /* ---------- 布局 ---------- */
  .layout { display: flex; }
  .sidebar {
