<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Wovra · 任务运行时可视化 Demo</title>
<style>
  :root {
    --bg: #0d1117;
    --bg2: #161b22;
    --panel: #1c2128;
    --border: #30363d;
    --text: #e6edf3;
    --dim: #8b949e;
    --acc: #58a6ff;
    --green: #3fb950;
    --amber: #d29922;
    --red: #f85149;
    --purple: #bc8cff;
    --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: var(--bg); color: var(--text);
    font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
    font-size: 14px; line-height: 1.5;
    padding: 20px;
  }
  .wrap { max-width: 1440px; margin: 0 auto; }
  header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 16px 20px; background: var(--bg2);
    border: 1px solid var(--border); border-radius: 12px; margin-bottom: 16px;
  }
  .logo { display: flex; align-items: center; gap: 12px; }
  .logo .dot {
    width: 12px; height: 12px; border-radius: 50%;
    background: var(--green); box-shadow: 0 0 12px var(--green);
    animation: pulse 2s infinite;
  }
  @keyframes pulse { 50% { opacity: .4; } }
  .logo h1 { font-size: 20px; font-weight: 700; letter-spacing: .5px; }
  .logo small { color: var(--dim); margin-left: 8px; font-weight: 400; }
  .task-id { font-family: var(--mono); color: var(--dim); font-size: 12px; }
  .status-pill {
    padding: 4px 12px; border-radius: 20px; font-size: 12px; font-weight: 600;
    background: rgba(63,185,80,.15); color: var(--green); border: 1px solid rgba(63,185,80,.3);
  }
  .grid { display: grid; gap: 16px; }
  .grid-top { grid-template-columns: 2fr 1fr; }
  .grid-mid { grid-template-columns: 1.4fr 1fr 1fr; }
  .grid-bottom { grid-template-columns: 1fr 1fr; }
  @media (max-width: 1000px) { .grid-top, .grid-mid, .grid-bottom { grid-template-columns: 1fr; } }
  .panel {
    background: var(--panel); border: 1px solid var(--border);
    border-radius: 12px; padding: 16px; min-width: 0;
  }
  .panel h2 {
    font-size: 13px; font-weight: 600; color: var(--dim);
    text-transform: uppercase; letter-spacing: 1px; margin-bottom: 12px;
    display: flex; align-items: center; justify-content: space-between;
  }
  .panel h2 .tag { font-size: 11px; color: var(--acc); text-transform: none; letter-spacing: 0; }

  /* ---- 上下文水位 ---- */
  .watermark { display: flex; align-items: baseline; gap: 12px; margin-bottom: 8px; }
  .watermark .num { font-size: 28px; font-weight: 700; font-family: var(--mono); }
  .watermark .of { color: var(--dim); font-size: 12px; }
  .bar { height: 10px; background: var(--bg2); border-radius: 6px; overflow: hidden; position: relative; }
  .bar .fill {
    height: 100%; border-radius: 6px; width: 8.7%;
    background: linear-gradient(90deg, var(--acc), var(--purple));
    transition: width .6s ease;
  }
  .bar .trigger {
    position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--amber);
    left: 10%; opacity: .7;
  }
  .bar-labels { display: flex; justify-content: space-between; margin-top: 6px; color: var(--dim); font-size: 11px; }
  .trigger-note { margin-top: 10px; font-size: 12px; color: var(--amber); background: rgba(210,153,34,.08); border: 1px dashed rgba(210,153,34,.3); border-radius: 8px; padding: 8px 10px; }
  .trigger-note code { font-family: var(--mono); color: var(--amber); }

  /* ---- 任务树 ---- */
  .task-tree { font-family: var(--mono); font-size: 13px; }
  .tree-row { display: flex; align-items: center; gap: 8px; padding: 4px 0; border-radius: 6px; cursor: pointer; }
  .tree-row:hover { background: rgba(88,166,255,.06); }
  .tree-row .icon { width: 20px; text-align: center; flex-shrink: 0; }
  .tree-row .label { color: var(--text); }
  .tree-row .label.done { color: var(--dim); text-decoration: line-through; }
  .tree-row .pct { margin-left: auto; color: var(--dim); font-size: 11px; }
  .tree-row.indent1 { padding-left: 28px; }
  .tree-row.indent2 { padding-left: 56px; }
  .tree-row .badge { font-size: 10px; padding: 1px 8px; border-radius: 10px; background: rgba(88,166,255,.15); color: var(--acc); }
  .tree-row .badge.done { background: rgba(63,185,80,.15); color: var(--green); }
  .tree-row .badge.pending { background: rgba(210,153,34,.15); color: var(--amber); }

  /* ---- 时间线 ---- */
  .timeline { position: relative; padding-left: 20px; }
  .timeline::before { content: ''; position: absolute; left: 6px; top: 4px; bottom: 4px; width: 2px; background: var(--border); }
  .tl-item { position: relative; padding: 8px 0 8px 12px; }
  .tl-item::before {
    content: ''; position: absolute; left: -19px; top: 14px;
    width: 10px; height: 10px; border-radius: 50%;
    background: var(--bg2); border: 2px solid var(--acc);
  }
  .tl-item.compacted::before { border-color: var(--dim); }
  .tl-item .tl-head { display: flex; gap: 8px; align-items: baseline; font-size: 12px; }
  .tl-item .tl-seq { font-family: var(--mono); color: var(--acc); font-weight: 600; }
  .tl-item .tl-user { color: var(--dim); font-size: 12px; }
  .tl-item .tl-summary { margin-top: 2px; font-size: 13px; color: var(--text); }
  .tl-item .tl-meta { margin-top: 2px; font-size: 11px; color: var(--dim); }
  .tl-item .chip { font-size: 10px; padding: 1px 8px; border-radius: 10px; margin-left: 4px; }
  .chip.org-done { background: rgba(63,185,80,.15); color: var(--green); }
  .chip.org-pending { background: rgba(210,153,34,.15); color: var(--amber); }
  .chip.raw { background: rgba(88,166,255,.1); color: var(--acc); }

  /* ---- 成本仪表 ---- */
  .cost-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px; }
  .cost-stat { background: var(--bg2); border-radius: 8px; padding: 10px 12px; }
  .cost-stat .v { font-size: 18px; font-weight: 700; font-family: var(--mono); }
  .cost-stat .k { font-size: 11px; color: var(--dim); margin-top: 2px; }
  .cost-stat .v.hit { color: var(--green); }
  .cost-stat .v.miss { color: var(--red); }
  .cost-stat .v.cny { color: var(--amber); }
  .mini-bar { height: 6px; border-radius: 3px; background: var(--bg2); overflow: hidden; margin-top: 8px; }
  .mini-bar .f { height: 100%; }
  .mini-bar .f.hit { background: var(--green); width: 99%; }
  .mini-bar .f.miss { background: var(--red); width: 1%; }

  /* ---- 域/分裂 ---- */
  .domain { display: flex; align-items: center; gap: 10px; padding: 10px; background: var(--bg2); border-radius: 8px; margin-bottom: 8px; border-left: 3px solid var(--acc); }
  .domain .d-icon { font-size: 18px; }
  .domain .d-name { font-weight: 600; }
  .domain .d-files { font-family: var(--mono); font-size: 11px; color: var(--dim); margin-top: 2px; }
  .domain .d-goal { font-size: 12px; color: var(--text); margin-top: 2px; }
  .split-note { font-size: 12px; color: var(--purple); background: rgba(188,140,255,.08); border: 1px dashed rgba(188,140,255,.3); border-radius: 8px; padding: 8px 10px; margin-top: 10px; }
  .split-note code { font-family: var(--mono); }

  /* ---- 维护管线 ---- */
  .pipeline { display: flex; gap: 8px; align-items: stretch; }
  .pipe-step { flex: 1; background: var(--bg2); border-radius: 8px; padding: 10px; text-align: center; border: 1px solid var(--border); position: relative; }
  .pipe-step .arrow { position: absolute; right: -10px; top: 50%; transform: translateY(-50%); color: var(--dim); }
  .pipe-step .st { font-size: 11px; color: var(--dim); }
  .pipe-step .st-val { font-size: 12px; font-weight: 600; margin-top: 4px; font-family: var(--mono); }
  .pipe-step.active { border-color: var(--acc); box-shadow: 0 0 12px rgba(88,166,255,.15); }
  .pipe-step.active .st-val { color: var(--acc); }
  .pipe-step.done .st-val { color: var(--green); }

  /* ---- 日志 ---- */
  .log { font-family: var(--mono); font-size: 12px; max-height: 180px; overflow-y: auto; }
  .log .l { padding: 3px 0; border-bottom: 1px solid rgba(48,54,61,.4); color: var(--dim); }
  .log .l .t { color: var(--dim); margin-right: 8px; }
  .log .l .msg { color: var(--text); }
  .log .l .msg.ok { color: var(--green); }
  .log .l .msg.warn { color: var(--amber); }
  .log .l .msg.err { color: var(--red); }

  footer { margin-top: 16px; text-align: center; color: var(--dim); font-size: 12px; }
</style>
</head>
