.badge.amber { background: rgba(217,161,59,.15); color: var(--amber); }
.badge.red { background: rgba(224,92,92,.15); color: var(--red); }
.badge.purple { background: rgba(169,124,240,.15); color: var(--purple); }
.badge.blue { background: rgba(79,140,255,.15); color: var(--accent); }
.stat-row { display: flex; justify-content: space-between; padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,.04); }
.stat-row:last-child { border-bottom: none; }
