.tl-item.done::before { background: var(--green); border-color: var(--green); }
.tl-item.active::before { background: var(--amber); border-color: var(--amber); }
.tl-seq { font-size: 11px; color: var(--dim); }
.tl-text { margin-top: 2px; }
/* 任务树 */
.tree { font-size: 13px; }
.tree .node { padding: 4px 0 4px 16px; border-left: 1px dashed var(--border); margin-left: 8px; }
.tree .node.root { border-left: none; padding-left: 0; margin-left: 0; }
/* 成本 */
.cost-big { font-size: 34px; font-weight: 700; color: var(--green); font-family: "JetBrains Mono", monospace; }
