{"content": "// Wovra 前端 Demo · 渲染逻辑
(function () {
  "use strict";

  // ---- 时间线 ----
  const tl = document.getElementById("timeline");
  if (tl) {
    TIMELINE.forEach(function (item) {
      const div = document.createElement("div");
      div.className = "tl-item " + item.state;
      div.innerHTML =
        '<span class="tl-seq">' + item.seq + "</span>" +
        '<div class="tl-text">' + item.text + "</div>";
      tl.appendChild(div);
    });
  }

  // ---- 成本仪表盘 ----
  const costPanel = document.getElementById("cost-panel");
  if (costPanel) {
    let total = 0;
    COST_PER_ROUND.forEach(function (c) { total += c.hit + c.miss; });

    const chart = document.createElement("div");
    chart.className = "bar-chart";
    COST_PER_ROUND.forEach(function (c) {
      const bar = document.createElement("div");
      const h = Math.max(4, (c.hit + c.miss) * 900);
      bar.className = "bar hit";
      bar.style.height = h + "%";
      bar.innerHTML = '<span class="bar-label">R' + c.r + "</span>";
      chart.appendChild(bar);
    });

    costPanel.innerHTML =
      '<div class="cost-big">¥' + total.toFixed(3) + "</div>" +
      '<div class="cost-note">12 轮累计 · hit ≈ 命中 · 演示数据</div>';
    costPanel.appendChild(chart);
  }

  // ---- 分裂示意 ----
  const splitPanel = document.getElementById("split-panel");
  if (splitPanel) {
    const box = document.createElement("div");
    box.className = "split-box";
    SPLIT_STAGES.forEach(function (stage) {
      const col = document.createElement("div");
      col.className = "split-col";
      col.innerHTML = '<div class="tag">' + stage.tag + "</div>" +
        "<div>" + stage.desc + "</div><br>" +
        stage.blocks.map(function (b) {
          return '<span class="badge blue">' + b + "</span> ";
        }).join("");
      box.appendChild(col);
    });
    splitPanel.appendChild(box);
  }

  // ---- 上下文层级 ----
  const ctxPanel = document.getElementById("ctx-panel");
  if (ctxPanel) {
    CONTEXT_LAYERS.forEach(function (layer) {
      const row = document.createElement("div");
      row.className = "stat-row";
      const kindColor =
        layer.kind === "static" ? "green" :
        layer.kind === "stable" ? "blue" :
        layer.kind === "dynamic" ? "amber" : "purple";
      row.innerHTML =
        '<span class="stat-label">' + layer.name +
        ' <span class="badge ' + kindColor + '">' + layer.kind + "</span></span>" +
        '<span class="stat-value">' + layer.note + "</span>";
      ctxPanel.appendChild(row);
    });
  }
})();
