{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Wovra · 对话工作台</title>
<style>
:root {
  --bg: #0b0e14;
  --panel: #131722;
  --panel-2: #1a2030;
  --border: #232a3b;
  --text: #d8dee9;
  --dim: #6b7488;
  --accent: #4f8cff;
  --green: #3fb96b;
  --amber: #d9a13b;
  --red: #e05c5c;
  --purple: #a97cf0;
  --user-bubble: #1e3a5f;
  --agent-bubble: #1a2030;
}
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  background: var(--bg); color: var(--text);
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 14px; height: 100vh; overflow: hidden;
}
/* ===== 三栏布局：左栏(会话列表) 中栏(聊天) 右栏(监控) ===== */
.layout { display: grid; grid-template-columns: 200px 1fr 240px; height: 100vh; }

/* ---- 左栏：会话列表 ---- */
.sidebar {
  background: var(--panel); border-right: 1px solid var(--border);
  padding: 14px; display: flex; flex-direction: column; gap: 8px; overflow-y: auto;
}
.sidebar .logo { font-size: 17px; font-weight: 700; letter-spacing: .5px; margin-bottom: 12px; }
.sidebar .logo span { color: var(--accent); }
.sess {
  padding: 10px; border-radius: 8px; border: 1px solid transparent; cursor: pointer;
  font-size: 12.5px; line-height: 1.4;
}
.sess:hover { background: var(--panel-2); }
.sess.active { background: var(--panel-2); border-color: var(--accent); }
.sess .t { font-weight: 600; margin-bottom: 3px; }
.sess .m { color: var(--dim); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sess .badge { float: right; }

/* ---- 中栏：聊天主区 ---- */
.chat {
  display: flex; flex-direction: column; height: 100vh; min-width: 0;
}
.chat-head {
  padding: 12px 18px; border-bottom: 1px solid var(--border);
  display: flex; align-items: center; gap: 10px; background: var(--panel);
}
.chat-head .title { font-weight: 600; font-size: 15px; }
.chat-head .sub { color: var(--dim); font-size: 12px; }
.messages { flex: 1; overflow-y: auto; padding: 18px; display: flex; flex-direction: column; gap: 14px; }

/* 消息气泡 */
.msg { display: flex; gap: 10px; max-width: 92%; }
.msg.user { align-self: flex-end; flex-direction: row-reverse; }
.msg .avatar {
  width: 30px; height: 30px; border-radius: 8px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; font-size: 14px;
}
.msg.user .avatar { background: var(--accent); }
.msg.agent .avatar { background: var(--panel-2); border: 1px solid var(--border); }
.msg .body {
  padding: 10px 14px; border-radius: 12px; line-height: 1.65; white-space: pre-wrap;
  word-break: break-word;
}
.msg.user .body { background: var(--user-bubble); border-top-right-radius: 4px; }
.msg.agent .body { background: var(--agent-bubble); border: 1px solid var(--border); border-top-left-radius: 4px; }

/* 工具调用卡片 */
.tool-card {
  margin-top: 8px; border: 1px solid var(--border); border-radius: 8px;
  overflow: hidden; font-size: 12px; background: rgba(0,0,0,.2);
}
.tool-card .tool-head {
  padding: 6px 10px; display: flex; justify-content: space-between; align-items: center;
  cursor: pointer; background: rgba(255,255,255,.03);
}
.tool-card .tool-name { font-family: "JetBrains Mono", Consolas, monospace; font-weight: 600; }
.tool-card .tool-detail { padding: 8px 10px; border-top: 1px solid var(--border); font-family: monospace; white-space: pre-wrap; display: none; color: var(--dim); }
.tool-card.open .tool-detail { display: block; }
.tool-card.ok .tool-name { color: var(--green); }
.tool-card.err .tool-name { color: var(--red); }

/* 轮次分隔 */
.round-divider {
  display: flex; align-items: center; gap: 10px; margin: 6px 0; color: var(--dim); font-size: 11.5px;
}
.round-divider::before, .round-divider::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.round-divider .tag { padding: 2px 8px; border-radius: 10px; background: var(--panel-2); }

/* 整理横幅 */
.org-banner {
  margin: 4px 0; padding: 8px 12px; border-radius: 8px; font-size: 12px;
  background: rgba(169,124,240,.08); border: 1px solid rgba(169,124,240,.25); color: var(--purple);
}

/* 输入区 */
.input-area {
  padding: 12px 18px; border-top: 1px solid var(--border); background: var(--panel);
  display: flex; gap: 10px; align-items: flex-end;
}
.input-area textarea {
  flex: 1; background: var(--panel-2); border: 1px solid var(--border); border-radius: 10px;
  color: var(--text); padding: 10px 12px; font-family: inherit; font-size: 13.5px;
  resize: none; max-height: 120px; outline: none;
}
.input-area textarea:focus { border-color: var(--accent); }
.input-area button {
  background: var(--accent); border: none; color: #fff; border-radius: 10px;
  padding: 10px 18px; font-size: 13.5px; cursor: pointer; font-weight: 600;
}
.input-area button:hover { filter: brightness(1.15); }

/* ---- 右栏：监控 ---- */
.monitor { background: var(--panel); border-left: 1px solid var(--border); padding: 14px; overflow-y: auto; }
.monitor h3 { font-size: 11px; color: var(--dim); text-transform: uppercase; letter-spacing: 1px; margin: 16px 0 8px; }
.monitor h3:first-child { margin-top: 0; }
.stat-row { display: flex; justify-content: space-between; padding: 5px 0; font-size: 12.5px; }
.stat-label { color: var(--dim); }
.stat-value { font-weight: 600; }
.meter { background: var(--panel-2); border-radius: 6px; height: 12px; overflow: hidden; margin: 6px 0; position: relative; }
.meter-fill { height: 100%; background: linear-gradient(90deg, var(--accent), var(--green)); border-radius: 6px; }
.meter-mark { position: absolute; top: -2px; bottom: -2px; width: 2px; background: var(--amber); }
.badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; }
.badge.green { background: rgba(63,185,107,.15); color: var(--green); }
.badge.amber { background: rgba(217,161,59,.15); color: var(--amber); }
.badge.purple { background: rgba(169,124,240,.15); color: var(--purple); }
.badge.blue { background: rgba(79,140,255,.15); color: var(--accent); }
.cost-big { font-size: 26px; font-weight: 700; color: var(--green); font-family: "JetBrains Mono", monospace; }
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
</style>
</head>
<body>
<div class="layout">
  <!-- 左栏：会话 -->
  <div class="sidebar" id="sidebar"></div>
  <!-- 中栏：聊天 -->
  <div class="chat">
    <div class="chat-head">
      <span class="title">agent-test</span>
      <span class="badge green">运行中</span>
      <span class="sub">· Wovra 执行助手 · 里程碑轮 R12</span>
    </div>
    <div class="messages" id="messages"></div>
    <div class="input-area">
      <textarea id="input" placeholder="给 Wovra 下达任务…（Enter 发送，Shift+Enter 换行）"></textarea>
      <button id="send">发送</button>
    </div>
  </div>
  <!-- 右栏：监控 -->
  <div class="monitor" id="monitor"></div>
</div>
<script src="data.js"></script>
<script src="app.js"></script>
</body>
</html>
", "path": "wovra-demo/index.html"}

