{"content": "// Wovra 对话工作台 · 渲染逻辑
(function () {
  "use strict";

  // ===== 会话列表 =====
  const sidebar = document.getElementById("sidebar");
  sidebar.innerHTML =
    '<div class="logo">Wov<span>ra</span></div>' +
    SESSIONS.map(function (s) {
      return '<div class="sess' + (s.active ? " active" : "") + '">' +
        '<span class="badge ' + s.badge[0] + '">' + s.badge[1] + "</span>" +
        '<div class="t">' + s.title + "</div>" +
        '<div class="m">' + s.preview + "</div>" +
        '<div class="m">' + s.time + "</div>" +
        "</div>";
    }).join("");

  // ===== 消息区 =====
  const messages = document.getElementById("messages");

  function toolCard(tool) {
    return '<div class="tool-card ' + tool.status + '" onclick="this.classList.toggle(\'open\')">' +
      '<div class="tool-head">' +
      '<span class="tool-name">' + tool.name + "</span>" +
      '<span>' + (tool.status === "ok" ? "✓" : "✗") + "</span>" +
      "</div>" +
      '<div class="tool-detail">' + tool.args + "</div>" +
      "</div>";
  }

  MESSAGES.forEach(function (m) {
    if (m.type === "round") {
      messages.insertAdjacentHTML("beforeend",
        '<div class="round-divider"><span class="tag">' + m.text + "</span></div>");
      return;
    }
    if (m.type === "org") {
      messages.insertAdjacentHTML("beforeend",
        '<div class="org-banner">⚡ ' + m.text + "</div>");
      return;
    }
    const tools = (m.tools || []).map(toolCard).join("");
    messages.insertAdjacentHTML("beforeend",
      '<div class="msg ' + m.type + '">' +
      '<div class="avatar">' + (m.type === "user" ? "你" : "W") + "</div>" +
      '<div class="body">' + m.text + tools + "</div>" +
      "</div>");
  });
  messages.scrollTop = messages.scrollHeight;

  // ===== 输入交互 =====
  const input = document.getElementById("input");
  const sendBtn = document.getElementById("send");
  function send() {
    const text = input.value.trim();
    if (!text) return;
    messages.insertAdjacentHTML("beforeend",
      '<div class="msg user"><div class="avatar">你</div><div class="body">' +
      text.replace(/</g, "&lt;") + "</div></div>");
    messages.insertAdjacentHTML("beforeend",
      '<div class="msg agent"><div class="avatar">W</div><div class="body">' +
      "（Demo：这是演示数据，真实对话需要后端接入）</div></div>");
    messages.scrollTop = messages.scrollHeight;
    input.value = "";
  }
  sendBtn.addEventListener("click", send);
  input.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
  });

  // ===== 右栏监控 =====
  const mon = document.getElementById("monitor");
  const M = MONITOR;
  mon.innerHTML =
    '<h3>任务</h3>' +
    '<div class="stat-row"><span class="stat-label">当前</span><span class="stat-value">' + M.task + "</span></div>" +
    '<div class="stat-row"><span class="stat-label">轮次</span><span class="stat-value">' + M.rounds + "</span></div>" +
    '<div class="stat-row"><span class="stat-label">模式</span><span class="stat-value">' + M.org + "</span></div>" +
    '<h3>上下文水位</h3>' +
    '<div class="meter">' +
    '<div class="meter-fill" style="width:' + M.water + '%"></div>' +
    '<div class="meter-mark" style="left:100%"></div></div>' +
    '<div class="stat-row"><span class="stat-label">估算</span><span class="stat-value">' + M.estimate + "</span></div>" +
    '<div class="stat-row"><span class="stat-label">窗口</span><span class="stat-value">' + M.window + "</span></div>" +
    '<div class="stat-row"><span class="stat-label">命中率</span><span class="stat-value" style="color:var(--green)">' + M.hitRate + "%</span></div>" +
    '<h3>成本</h3>' +
    '<div class="cost-big">¥' + M.cost.toFixed(3) + "</div>" +
    '<div class="stat-row" style="margin-top:6px"><span class="stat-label" style="font-size:11px">' + M.costNote + "</span></div>" +
    '<h3>活性文件域</h3>' +
    M.domains.map(function (d) {
      return '<div class="stat-row"><span class="stat-label">' + d.name +
        "</span><span class='stat-value'>" + d.files + " 文件</span></div>";
    }).join("") +
    '<h3>分裂判定</h3>' +
    '<div style="font-size:12px;line-height:1.5;background:var(--panel-2);border:1px solid var(--border);border-radius:8px;padding:8px 10px;">' +
    '<span class="badge ' + (M.split.splittable ? "green" : "amber") + '">' +
    (M.split.splittable ? "可分" : "不可分") + "</span> " +
    M.split.reason + "</div>";
})();
